// === Strip markdown from the agent answer ===
// Telegram is sent without a parse mode, so markdown signs would show up as plain text.
// The prompt forbids markdown, but the model still uses it now and then.
const clean = (s) => String(s ?? '')
  .replace(/\*\*(.+?)\*\*/gs, '$1')   // **bold** -> bold
  .replace(/^#{1,6}\s+/gm, '')         // # headings -> plain line
  .replace(/^\s*\*\s+/gm, '- ');      // "* item" -> "- item"

// === Keep all fields, only replace the answer text ===
return $input.all().map(i => ({ json: { ...i.json, output: clean(i.json.output) } }));

// === Check Sources ===
// Rule-based check of the agent answer against the hits (no extra model call).
// 1) A sentence with a number and unit (e.g. "20 Mitarbeiter", "sechs Monate", "2 %") must appear in the
//    law text of the articles the answer cites (or in all hits if the answer cites none).
//    Otherwise the sentence is removed (or only flagged, see NUMBER_MODE).
// 2) An article cited in the answer (e.g. "DSGVO Art. 25") that is not among the hits gets a note.

// === Constants ===
const NUMBER_MODE = 'remove';   // 'remove' = delete the sentence, 'warn' = only add a note, 'off' = no check
const CITATION_MODE = 'warn';   // 'warn' = add a note, 'off' = no check
const WORDS = { zwei: 2, drei: 3, vier: 4, fünf: 5, sechs: 6, sieben: 7, acht: 8, neun: 9, zehn: 10, elf: 11, zwölf: 12, zwanzig: 20, dreißig: 30, vierzig: 40, fünfzig: 50, hundert: 100 };
const DATE_RE = /\b\d{1,2}\.\s*(?:Januar|Februar|März|April|Mai|Juni|Juli|August|September|Oktober|November|Dezember)\s+\d{4}\b/g;   // e.g. "2. Dezember 2027"
const WORD_OF = Object.fromEntries(Object.entries(WORDS).map(([w, n]) => [n, w]));
const TIME = '(?:Monat|Jahr|Tag|Woche|Stunde)\\w*';
const PEOPLE = '(?:Mitarbeiter|Personen|Beschäftigte)\\w*';

const item = $input.first().json;
const answer = String(item.output ?? '');
const agentItem = $('AI Agent').first().json;   // the cards come straight from the agent
const steps = Array.isArray(agentItem.intermediateSteps) ? agentItem.intermediateSteps : [];

// === No search in this turn (refusal, topic list): nothing to check against ===
if (steps.length === 0) {
  return [{ json: { output: answer, checks: { skipped: 'no search in this turn' } } }];
}

// === Parse the hits: each card is a JSON block with pageContent and metadata.fundstelle ===
const cards = [];
for (const s of steps) {
  try {
    const arr = typeof s.observation === 'string' ? JSON.parse(s.observation) : s.observation;
    for (const r of (arr ?? [])) for (const part of (r.response ?? [])) {
      const doc = JSON.parse(part.text);
      cards.push({ fundstelle: String(doc.metadata?.fundstelle ?? ''), text: String(doc.pageContent ?? '') });
    }
  } catch (e) { /* unknown format: fall back to the raw text below */ }
}
const rawText = steps.map(s => (typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation ?? ''))).join('\n');
const allText = cards.length ? cards.map(c => c.text).join('\n') : rawText;
const keyOf = (txt) => { const m = txt.match(/(DSGVO|EU AI Act)\s*Art\.?\s*(\d+)/); return m ? m[1] + ' Art. ' + m[2] : null; };
const hitArticles = new Set(cards.length
  ? cards.map(c => keyOf(c.fundstelle)).filter(Boolean)
  : [...rawText.matchAll(/(DSGVO|EU AI Act)\s*Art\.?\s*(\d+)/g)].map(m => m[1] + ' Art. ' + m[2]));

// === Articles cited in the answer ===
const cited = new Set();
const citedMissing = new Set();
let law = null;
for (const m of answer.matchAll(/(DSGVO|EU AI Act)|Art\.?\s*(\d+)/g)) {
  if (m[1]) { law = m[1]; continue; }
  if (!law) continue;
  const key = law + ' Art. ' + m[2];
  cited.add(key);
  if (!hitArticles.has(key)) citedMissing.add(key);
}

// Text the numbers are checked against: cards of the cited articles, otherwise all hits
const citedCards = cards.filter(c => cited.has(keyOf(c.fundstelle)));
const refText = citedCards.length ? citedCards.map(c => c.text).join('\n') : allText;

// === Check 1: numbers with unit ===
const forms = (n) => [String(n), WORD_OF[n]].filter(Boolean).join('|');
const inRef = (n, unit) => new RegExp('\\b(?:' + forms(n) + ')\\s*' + unit, 'i').test(refText);
const numRe = new RegExp('\\b(\\d+|' + Object.keys(WORDS).join('|') + ')\\s*(' + TIME + '|' + PEOPLE + '|%|Prozent|Mio\\.?|Millionen)', 'gi');
const unsupported = (sentence) => {
  const bad = [];
  // dates: every date in the sentence must appear in the hits (protects against invented dates)
  for (const d of sentence.matchAll(DATE_RE)) { if (!allText.includes(d[0])) bad.push(d[0]); }
  for (const m of sentence.matchAll(numRe)) {
    const n = /^\d+$/.test(m[1]) ? Number(m[1]) : WORDS[m[1].toLowerCase()];
    const unit = m[2];
    let ok;
    if (/^(%|Prozent)$/i.test(unit)) ok = new RegExp('\\b' + n + '\\s*(%|Prozent)').test(refText);
    else if (/^(Mio|Millionen)/i.test(unit)) ok = new RegExp('\\b' + n + '\\b').test(refText);   // amounts are written as 10 000 000 in the law
    else if (new RegExp('^' + PEOPLE + '$', 'i').test(unit)) ok = inRef(n, PEOPLE);
    else ok = inRef(n, TIME);
    if (!ok) bad.push(m[0]);
  }
  return bad;
};

// Keep abbreviations together so they do not split a sentence.
// A private marker (not whitespace) replaces the space, because \s would also match a non-breaking space.
const protect = (s) => s.replace(/\b(z|B|Mio|Abs|Art|Nr|lit|ca|bzw|u|a|d|h|ggf|vgl|inkl|evtl)\.\s/g, '$1.\u0001');
const restore = (s) => s.replace(/\u0001/g, ' ');

const removed = [];
let cleaned = answer;
if (NUMBER_MODE !== 'off') {
  const origLines = answer.split('\n');
  const lines = origLines.map(line => {
    const sentences = protect(line).split(/(?<=[.!?])\s+(?=[A-ZÄÖÜ"(])/);
    const kept = [];
    for (const s of sentences) {
      const bad = unsupported(restore(s));
      if (bad.length) { removed.push(...bad); if (NUMBER_MODE === 'remove') continue; }
      kept.push(s);
    }
    return restore(kept.join(' '));
  });
  // drop lines that became empty because their only sentence was removed
  cleaned = lines.filter((l, i) => l.trim() !== '' || origLines[i].trim() === '').join('\n').trim();
}

// === Notes for the reader (language of the answer) ===
const en = /\b(the|and|you|your|which|that)\b/i.test(answer);
const notes = [];
if (removed.length && NUMBER_MODE === 'remove') notes.push(en ? 'Note: a statement without a source in the retrieved law texts was removed.' : 'Hinweis: Eine Angabe ohne Beleg in den abgerufenen Gesetzestexten wurde entfernt.');
if (removed.length && NUMBER_MODE === 'warn') notes.push(en ? 'Note: not found in the retrieved law texts: ' + removed.join(', ') : 'Hinweis: Nicht in den abgerufenen Gesetzestexten gefunden: ' + removed.join(', '));
if (citedMissing.size && CITATION_MODE === 'warn') notes.push(en ? 'Note: citation not among the retrieved hits, please check: ' + [...citedMissing].join(', ') : 'Hinweis: Fundstelle nicht unter den abgerufenen Treffern, bitte prüfen: ' + [...citedMissing].join(', '));

if (cleaned === '') cleaned = answer;   // never return an empty answer
const output = notes.length ? cleaned + '\n\n' + notes.join('\n') : cleaned;

// intermediateSteps are dropped here (large), only the result and a small check log go on
return [{ json: { output, checks: { steps: steps.length, cards: cards.length, hitArticles: hitArticles.size, removed, citedMissing: [...citedMissing] } } }];

// === Constants ===
const DAY_LIMIT_EUR = 1.00;   // same value as DAY_LIMIT_EUR in compliance-bot-cost-per-question

// === Sum of today's real questions (rows come from Get Today's Rows) ===
const todaySum = $input.all().reduce((s, i) => s + Number(i.json.cost_eur ?? 0), 0);

// === Pass the question on, the agent reads chatInput and sessionId ===
const q = $('Reset Check').first().json;
return [{ json: { chatInput: q.chatInput, sessionId: q.sessionId, todaySum, limit: DAY_LIMIT_EUR, overLimit: todaySum >= DAY_LIMIT_EUR } }];

// === Memory reset with /neu ===
// The agent memory is keyed by sessionId. /neu starts a new session id, so the old conversation is no longer used.
const store = $getWorkflowStaticData('global');
store.sessionEpoch = store.sessionEpoch ?? {};

// === Question from Telegram Input ===
const q = $('Telegram Input').first().json;
const chatId = String(q.sessionId).replace('tg-', '');
const isReset = String(q.chatInput).trim().toLowerCase().startsWith('/neu');

// === /neu remembers a new epoch for this chat, the session id gets it as suffix ===
if (isReset) store.sessionEpoch[chatId] = Date.now();
const epoch = store.sessionEpoch[chatId];

return [{ json: { chatInput: q.chatInput, sessionId: 'tg-' + chatId + (epoch ? '-' + epoch : ''), isReset } }];

// === Prepare Verification ===
// Builds the input for the verifier: the answer plus the law cards the agent retrieved.
const MAX_CARD_CHARS = 4500;     // cut very long cards
const MAX_TOTAL_CHARS = 90000;   // upper bound for the whole card block

const item = $input.first().json;
const answer = String(item.output ?? '');
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];

// === Parse the cards (same format as in Check Sources) ===
const cards = [];
for (const s of steps) {
  try {
    const arr = typeof s.observation === 'string' ? JSON.parse(s.observation) : s.observation;
    for (const r of (arr ?? [])) for (const part of (r.response ?? [])) {
      const doc = JSON.parse(part.text);
      cards.push('[' + String(doc.metadata?.fundstelle ?? '') + ']\n' + String(doc.pageContent ?? '').slice(0, MAX_CARD_CHARS));
    }
  } catch (e) { /* unknown format: skip this step */ }
}
let block = cards.join('\n\n---\n\n');
if (block.length > MAX_TOTAL_CHARS) block = block.slice(0, MAX_TOTAL_CHARS);

return [{ json: { verifyInput: 'ANTWORT:\n' + answer + '\n\nKARTEN:\n' + block, cardCount: cards.length, inputChars: block.length } }];

// === Apply Verification ===
// Uses the verifier result for the agent answer.
// Modes: 'log' = only write the finding into the execution data (answer unchanged),
//        'warn' = append a note to the answer, 'remove' = delete the flagged sentences.
const VERIFY_MODE = 'log';

const agent = $('AI Agent').first().json;
const prep = $('Prepare Verification').first().json;   // diagnostics: how many cards did the verifier get
const answer = String(agent.output ?? '');
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];
const flagged = $input.first().json.output?.unbelegt ?? [];

// === No search in this turn (refusal, topic list, counter-question): nothing to verify ===
if (steps.length === 0) {
  return [{ json: { output: answer, verification: { skipped: 'no search in this turn' } } }];
}

// === Only sentences that really occur in the answer count (the model must quote word for word) ===
const plain = answer.replace(/\*\*/g, '');   // flagged sentences are quoted without bold signs
const found = flagged.filter(s => s && plain.includes(s));
let output = VERIFY_MODE === 'remove' ? plain : answer;
if (VERIFY_MODE === 'remove') {
  for (const s of found) output = output.replace(s, '');
  output = output.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (output === '') output = answer;   // never return an empty answer
}

// === Note for the reader (language of the answer) ===
const en = /\b(the|and|you|your|which|that)\b/i.test(answer);
if (VERIFY_MODE !== 'log' && found.length) {
  const removed = VERIFY_MODE === 'remove';
  output += '\n\n' + (removed
    ? (en ? 'Note: a statement without a source in the retrieved law texts was removed.' : 'Hinweis: Eine Aussage ohne Beleg in den abgerufenen Gesetzestexten wurde entfernt.')
    : (en ? 'Note: some statements are not backed by the retrieved law texts, please check.' : 'Hinweis: Einzelne Aussagen sind in den abgerufenen Gesetzestexten nicht belegt, bitte prüfen.'));
}

// Check Sources reads the cards from the agent node, the finding stays in the execution data
return [{ json: { output, verification: { mode: VERIFY_MODE, flagged: flagged.length, found: found.length, sentences: found, allFlagged: flagged, cards: prep.cardCount, inputChars: prep.inputChars } } }];

// === Add AI notice ===
// Appends a fixed line to every answer: the bot is an AI assistant and gives no legal advice.
// The workflow adds it (not the model), so it can not be forgotten.

// === Constants ===
const NOTICE_DE = 'Hinweis: Ich bin ein KI-Assistent und gebe keine Rechtsberatung.';
const NOTICE_EN = 'Note: I am an AI assistant and do not give legal advice.';

// === Per answer: pick the language (same simple check as in Check Sources), append the line ===
return $input.all().map(i => {
  const answer = String(i.json.output ?? '');
  const en = /\b(the|and|you|your|which|that)\b/i.test(answer);
  return { json: { ...i.json, output: answer + '\n\n' + (en ? NOTICE_EN : NOTICE_DE) } };
});
